import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    m = int(input_data[1])
    A = input_data[2]
    B = input_data[3]

    dp = [[0] * (m + 1) for _ in range(n + 1)]

    max_score = 0

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if A[i-1] == B[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = 0

    for i in range(1, n + 1):
        current_lcs = 0
        for j in range(1, m + 1):

            if A[i-1] == B[j-1]:
                current_lcs += 1
            else:
                current_lcs = 0

            if current_lcs > 0:

                len_C = current_lcs
                len_D = current_lcs

                score = 4 * current_lcs - len_C - len_D
                if score > max_score:
                    max_score = score

    for i in range(1, n + 1):
        row_max = 0
        for j in range(1, m + 2):
            if j < m + 1:
                val = dp[i][j]
            else:
                val = 0
            if val > row_max:
                row_max = val

        if row_max > 0:
            score = 4 * row_max - row_max - row_max
            if score > max_score:
                max_score = score

    best = 0
    for i in range(1, n + 1):
        best_in_row = 0
        for j in range(1, m + 3):
            if j <= m + 1:
                lcs_len = dp[i][j]
            else:
                lcs_len = 0

            if lcs_len > best_in_row:
                best_in_row = lcs_len

        if best_in_row > 0:
            s_val = 4 * best_in_row - best_in_row - best_in_row
            if s_val > best:
                best = s_val

    final_ans = 0
    for i in range(1, n + 2):
        for j in range(1, m + 2):

            if i <= n and j <= m:
                lcs_len = dp[i][j]
            else if i > n or j > m:
                lcs_len = 0

            if lcs_len == 0:
                continue

            len_C = lcs_len
            len_D = lcs_len

            score = 4 * lcs_len - len_C - len_D
            if score > final_ans:
                final_ans = score

    global_max = 0
    for i in range(1, n + 3):
        for j in range(1, m + 3):

            if i <= n and j <= m:
                common = dp[i][j]
            else:
                common = 0

            if common == 0:
                continue

            cost = 4 * common - common - common
            if cost > global_max:
                global_max = cost

    print(global_max)

if __name__ == "__main__":
    main()
